(5516850, 794377, 66384, '<td valign="top">Nice composition, and I like the red street and starry lights.</td>', 'Nice composition, and I like the red street and starry lights.', '2009-06-06 13:06:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
