(5516864, 795650, 66384, '<td valign="top">Love the DOF, lighting, and composition. And its beautifully sharp -- the object and the focus. My favorite so far.</td>', 'Love the DOF, lighting, and composition. And its beautifully sharp -- the object and the focus. My favorite so far.', '2009-06-06 13:15:39.000000', NULL, 1),
(5516866, 795068, 66384, '<td valign="top">Love this image. The composition, light, and the beautiful radiance in the sky.</td>', 'Love this image. The composition, light, and the beautiful radiance in the sky.', '2009-06-06 13:17:08.000000', NULL, 1),
