(5520094, 794450, 89230, '<td valign="top">Congratulations Cory! What a great perspective! I really like the post processing too! Stay safe bud</td>', 'Congratulations Cory! What a great perspective! I really like the post processing too! Stay safe bud', '2009-06-08 14:22:47.000000', NULL, 0),
(5520170, 795203, 61961, '<td valign="top">"Let them eat cake" as in "Off with their heads?"  Unusual object for sure.  It appears to be huge.  I like how the cloud makes it seem the arm is steaming.</td>', '"Let them eat cake" as in "Off with their heads?"  Unusual object for sure.  It appears to be huge.  I like how the cloud makes it seem the arm is steaming.', '2009-06-08 14:56:13.000000', NULL, 0),
(5520178, 795028, 61961, '<td valign="top">Strange monument.  Is this the same location as in Judi''s entry?<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=794911" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/1000-1999/1042/120/Copyrighted_Image_Reuse_Prohibited_794911.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/1000-1999/1042/120/Copyrighted_Image_Reuse_Prohibited_794911.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/1000-1999/1042/120/Copyrighted_Image_Reuse_Prohibited_794911.jpg"/></a></td>', 'Strange monument.  Is this the same location as in Judi''s entry?', '2009-06-08 15:02:27.000000', NULL, 0),
(5520185, 795068, 52549, '<td valign="top">Sorry you didn''t get your ribbon, Brent. I''d have wished you a joint Yellow. This is a very beautiful image and perfect for the challenge. Congrats on the HM though.</td>', 'Sorry you didn''t get your ribbon, Brent. I''d have wished you a joint Yellow. This is a very beautiful image and perfect for the challenge. Congrats on the HM though.', '2009-06-08 15:07:44.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5520189, 794169, 80908, '<td valign="top">44th place is not right. I gave this 9 (the highest I gave anyone) and genuinely expected to see it in the top 5. :o(</td>', '44th place is not right. I gave this 9 (the highest I gave anyone) and genuinely expected to see it in the top 5. :o(', '2009-06-08 15:13:38.000000', NULL, 0),
